.crypto-label {
  font-weight: 600;
  white-space: nowrap;
}

.crypto-button {
  min-inline-size: initial;
  margin-block: 0;
  margin-inline-end: 3px;
  fill: currentColor;
  background-color: transparent;
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  flex-direction: row;
  gap: 3px;

  & > * {
    vertical-align: middle;
  }
}

